// Generated from rules.yml by scripts/gen-privacy-rules.mjs. Do not edit.
export const RULES_YAML: string = "# status: draft — rule set to be authored/approved by Joel\n#\n# Sensitive-combination rules. Each one is deterministic: it looks only at which categories are present.\n# A selector is an exact category id, an id ending in .* (it and everything under it), or an @tag:\n#   @gdpr_art9  @cpra_sensitive  @hipaa_identifier  @direct_identifier  @quasi_identifier  @childrens\n# `when.any` fires if any selector is present. `when.all` fires if every group has a present selector.\n# A rule cites its sources and states what the rule says. It does not say whether anyone meets it.\nstatus: draft — rule set to be authored/approved by Joel\nrules:\n  - id: gdpr-art9-special-category\n    title: GDPR special category data\n    summary: >-\n      This data includes a category that GDPR Art. 9(1) lists as a special category. Art. 9(1) prohibits processing\n      these categories unless one of the conditions in Art. 9(2) applies.\n    sources:\n      - \"GDPR Art. 9(1)\"\n      - \"GDPR Art. 9(2)\"\n    when:\n      any: [\"@gdpr_art9\"]\n\n  - id: cpra-sensitive-personal-information\n    title: CPRA sensitive personal information\n    summary: >-\n      This data includes a category that Cal. Civ. Code §1798.140(ae) defines as sensitive personal information.\n      Section 1798.121 gives California consumers a right to limit its use and disclosure.\n    sources:\n      - \"Cal. Civ. Code §1798.140(ae)\"\n      - \"Cal. Civ. Code §1798.121\"\n    when:\n      any: [\"@cpra_sensitive\"]\n\n  - id: hipaa-identifier-with-health\n    title: HIPAA identifier next to health data\n    summary: >-\n      Health information sits alongside a data element on the HIPAA Safe Harbor identifier list. Safe Harbor\n      de-identification under 45 CFR §164.514(b)(2)(i) requires removing all 18 listed identifier types. The rule\n      reaches covered entities and their business associates.\n    sources:\n      - \"45 CFR §164.514(b)(2)(i)(A)-(R)\"\n    when:\n      all:\n        - any: [\"@hipaa_identifier\"]\n        - any: [\"user.health_and_medical\"]\n\n  - id: coppa-child-under-13\n    title: Data about children under 13\n    summary: >-\n      This data includes a field about children. The COPPA Rule at 16 CFR §312.2 defines a child as under 13, and\n      §312.5 requires verifiable parental consent before collecting personal information from one.\n    sources:\n      - \"16 CFR §312.2\"\n      - \"16 CFR §312.5\"\n    when:\n      any: [\"@childrens\"]\n\n  - id: precise-geolocation-with-direct-identifier\n    title: Precise location joined with a direct identifier\n    summary: >-\n      Precise geolocation is sensitive personal information under Cal. Civ. Code §1798.140(ae), and GDPR Art. 4(1)\n      names location data as something that can identify a person. Here it appears with a direct identifier.\n    sources:\n      - \"Cal. Civ. Code §1798.140(ae)\"\n      - \"GDPR Art. 4(1)\"\n    when:\n      all:\n        - any: [\"user.location.precise\"]\n        - any: [\"@direct_identifier\"]\n";
